SELECT t1.*, round((t1.net_cf_item10 * (1 + t1.vat_rate)), 2) due_cf_item10, (round((t1.net_cf_item10 * (1 + t1.vat_rate)), 2) - t1.net_cf_item10) vat_cf_item10,
round((t1.net_cf_item1 * (1 + t1.vat_rate)), 2) due_cf_item1, (round((t1.net_cf_item1 * (1 + t1.vat_rate)), 2) - t1.net_cf_item1) vat_cf_item1,
round((t1.net_cf_item3 * (1 + t1.vat_rate)), 2) due_cf_item3, (round((t1.net_cf_item3 * (1 + t1.vat_rate)), 2) - t1.net_cf_item3) vat_cf_item3,
round((t1.net_cf_item65 * (1 + t1.vat_rate)), 2) due_cf_item65, (round((t1.net_cf_item65 * (1 + t1.vat_rate)), 2) - t1.net_cf_item65) vat_cf_item65,
round((t1.net_cf_item501 * (1 + t1.vat_rate)), 2) due_cf_item501, (round((t1.net_cf_item501 * (1 + t1.vat_rate)), 2) - t1.net_cf_item501) vat_cf_item501,
round((t1.net_cf_item69 * (1 + t1.vat_rate)), 2) due_cf_item69, (round((t1.net_cf_item69 * (1 + t1.vat_rate)), 2) - t1.net_cf_item69) vat_cf_item69
FROM (SELECT (select p.contract_number from con_contract c,prj_project p where c.project_id = p.project_id and c.contract_id = t.contract_id) contract_number, (SELECT c.contract_number FROM con_contract c WHERE c.contract_id = t.contract_id) payment_number, (SELECT c.contract_name FROM con_contract c WHERE c.contract_id = t.contract_id) contract_name, (SELECT m.bp_name FROM con_contract c, hls_bp_master m WHERE c.contract_id = t.contract_id AND c.tenant_id = m.bp_id) bp_name, t.period_name, t.amortization_date, (SELECT c.vat_rate FROM con_contract c WHERE c.contract_id = t.contract_id) vat_rate, (SELECT SUM(tt.amortization_amount) FROM gld_finance_income_day tt WHERE tt.amortization_date = t.amortization_date AND tt.contract_id = t.contract_id AND tt.cf_item = 10) net_cf_item10, (SELECT SUM(tt.amortization_amount) FROM gld_finance_income_day tt WHERE tt.amortization_date = t.amortization_date AND tt.contract_id = t.contract_id AND tt.cf_item = 1) net_cf_item1, (SELECT SUM(tt.amortization_amount) FROM gld_finance_income_day tt WHERE tt.amortization_date = t.amortization_date AND tt.contract_id = t.contract_id AND tt.cf_item = 3) net_cf_item3, (SELECT SUM(tt.amortization_amount) FROM gld_finance_income_day tt WHERE tt.amortization_date = t.amortization_date AND tt.contract_id = t.contract_id AND tt.cf_item = 65) net_cf_item65,
(SELECT SUM(tt.amortization_amount) FROM gld_finance_income_day tt WHERE tt.amortization_date = t.amortization_date AND tt.contract_id = t.contract_id AND tt.cf_item = 501) net_cf_item501,
(SELECT SUM(tt.amortization_amount) FROM gld_finance_income_day tt WHERE tt.amortization_date = t.amortization_date AND tt.contract_id = t.contract_id AND tt.cf_item = 69) net_cf_item69
FROM gld_finance_income_day t GROUP BY t.contract_id, t.amortization_date, t.period_name) t1
1=1
AND t1.amortization_date >= #{amortizationDateFrom}
AND t1.amortization_date <= #{amortizationDateTo}
AND t1.period_name = #{periodName}
and t1.contract_number like #{contractNumber}
and t1.contract_name like #{contractName}
and t1.bp_name like #{bpName}
order by t1.contract_number,t1.amortization_date

select t.* from gld_finance_income_day t

    1=1
    and t.contract_id = #{contractId}
    and (t.cf_item = 1 or t.cf_item = 10)
    and t.amortization_date < #{leaseAccountDate}

