insert into gld_finance_income_day ( finance_income_day_id, company_id, contract_id, cashflow_id, cf_item, period_name, amortization_date, pre_amortization_amount, adjustment_amount, amortization_amount, object_version_number, request_id, program_id, created_by, creation_date, last_updated_by, last_update_date, last_update_login ) SELECT gld_finance_income_day_s.nextval id, t.* FROM (
SELECT #{item.companyId} company_id, #{item.contractId} contract_id, #{item.cashflowId} cashflow_id, #{item.cfItem} cf_item, #{item.periodName} period_name, #{item.amortizationDate} amortization_date, #{item.preAmortizationAmount} pre_amortization_amount, #{item.adjustmentAmount} adjustment_amount, #{item.amortizationAmount} amortization_amount, 1 object_version_number, 1 request_id, 1 program_id, 1 created_by, sysdate creation_date, 1 last_updated_by, sysdate last_update_date, 1 last_update_login from dual
)t
